  "internationalizedSource": ""use client";
import { useTranslations } from 'next-intl';

import { useState } from "react";

import { createClient } from "@/lib/supabase/client";
import { checkLoginRateLimit } from "@/app/(auth)/login/actions";
import { Button } from "@/components/ui/button";
import { TERMS_COOKIE, TERMS_VERSION } from "@/lib/terms";

/** Cookie corta para volver al sorteo después del login con Google. */
const NEXT_COOKIE = "gadu_next";

export function GoogleAuthButton({
  const t = useTranslations('GoogleAuthButton');
  next,
  termsAccepted = true,
}: {
  next?: string | null;
  termsAccepted?: boolean;
}) {
  const supabase = createClient();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  function safeNext(): string | null {
    if (!next) return null;
    return next.startsWith("/") && !next.startsWith("//") ? next : null;
  }

  async function handleSignIn() {
    if (!termsAccepted) return;
    setLoading(true);
    setError(null);

    // Protección perimetral antes de iniciar OAuth: 5 intentos/15 min por IP.
    const gate = await checkLoginRateLimit();
    if (!gate.ok) {
      setError(gate.error);
      setLoading(false);
      return;
    }

    const target = safeNext();
    if (target) {
      document.cookie = `${NEXT_COOKIE}=${encodeURIComponent(
        target,
      )}; Path=/; Max-Age=600; SameSite=Lax`;
    } else {
      document.cookie = `${NEXT_COOKIE}=; Path=/; Max-Age=0; SameSite=Lax`;
    }

    // Evidencia de que tildó el checkbox; el callback la guarda en el perfil y
    // deja la cookie de un año para no volver a pedirlo mientras no cambie la versión.
    document.cookie = `${TERMS_COOKIE}=${encodeURIComponent(
      TERMS_VERSION,
    )}; Path=/; Max-Age=600; SameSite=Lax`;

    const { error } = await supabase.auth.signInWithOAuth({
      provider: "google",
      options: {
        redirectTo: `${window.location.origin}/auth/callback`,
      },
    });

    if (error) {
      console.error("Error iniciando Google OAuth:", error.message);
      setLoading(false);
    }
    // En éxito NO se desactiva loading: el navegador es redirigido a Google.
  }

  return (
    <div className="space-y-2">
      <Button
        type="button"
        variant="outline"
        className="w-full shadow-sm"
        onClick={handleSignIn}
        disabled={loading || !termsAccepted}
      >
        <svg className="mr-2 h-4 w-4" viewBox="0 0 24 24" aria-hidden="true">
          <path
            fill="#4285F4"
            d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
          />
          <path
            fill="#34A853"
            d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
          />
          <path
            fill="#FBBC05"
            d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
          />
          <path
            fill="#EA4335"
            d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
          />
        </svg>
        {loading ? "Redirigiendo…" : "Continuar con Google"}
      </Button>
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
    </div>
  );
}
",
  "messageJson": {
